def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_caps = []
    urgent_opp_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                opp_caps.append(float(bid))
            else:
                opp_caps.append(float(opp.get('daily_salary', DAILY_SALARY)) * 0.6)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp_count += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units_available = supply / float(WATER_REQ)
    tight_supply = supply <= 18
    very_tight_supply = supply <= 15.5
    looser_supply = supply >= 22

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    if very_tight_supply:
        danger += 2
    elif tight_supply:
        danger += 1

    if urgent_opp_count >= 2:
        danger += 1

    if day >= 8:
        danger += 1

    if danger <= 1:
        base = max(18.0, avg_prev * 0.72)
        if highest_prev >= 80:
            base = min(base, 38.0)
        elif highest_prev <= 65 and tight_supply:
            base = max(base, highest_prev + 2.0)
    elif danger <= 3:
        target = max(48.0, min(66.0, second_prev + 3.0))
        if highest_prev <= 65:
            target = max(target, highest_prev + 2.0)
        if tight_supply:
            target += 3.0
        base = target
    else:
        target = max(62.0, highest_prev + 2.0)
        if highest_prev >= 95:
            target = 97.0
        elif highest_prev >= 80:
            target = highest_prev + 1.0
        if very_tight_supply:
            target += 4.0
        base = target

    if looser_supply and danger <= 2:
        base -= 6.0

    reserve_floor = 0.0
    if day <= 6:
        reserve_floor = 35.0
    elif day <= 8:
        reserve_floor = 20.0

    max_affordable = budget - reserve_floor
    if max_affordable < 0:
        max_affordable = budget

    bid = min(base, max_affordable)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, max(75.0, highest_prev + 2.0)))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        bid = avg_prev + 2.0
    else:
        bid = DAILY_SALARY * 0.4

    if my_status['hp'] < 4:
        bid = max(bid, DAILY_SALARY * 0.6)

    return min(my_status['budget'], float(bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    SALARY = 140
    supply = day_context['supply']
    supply_int = int(supply)
    hp = my_status['hp']
    budget = my_status['budget']

    # Collect yesterday's bids from alive opponents
    prev_bids = []
    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            trace = opp.get('previous_trace')
            if trace and trace.get('bid') is not None:
                prev_bids.append(trace['bid'])

    # Base bid depending on health
    if hp <= 1:
        bid = min(budget, SALARY * 0.8)
    elif hp <= 3:
        bid = min(budget, SALARY * 0.5)
    else:
        bid = min(budget, SALARY * 0.3)

    # Adjust using previous opponents' bids and current supply
    if prev_bids:
        avg_prev = sum(prev_bids) / len(prev_bids)
        if supply_int < 20:
            target = min(budget, max(avg_prev + 5, SALARY * 0.5))
        else:
            target = min(budget, max(avg_prev - 10, SALARY * 0.2))
        if hp <= 1:
            target = max(target, SALARY * 0.7)
        bid = min(budget, target)

    return float(bid)
